const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";

const [a, b] = await Promise.all([
  fs.readFile(S+"\\_GIG50_RESULT.json","utf8").then(JSON.parse).catch(()=>[]),
  fs.readFile(S+"\\_GIG_EXTRA_RESULT.json","utf8").then(JSON.parse).catch(()=>[])
]);

// 合并并按类型分组：只要「能接活」的
const GIG_HOSTS = {
  "🌍 全球自由职业": ["freelancer.com","upwork.com","fiverr.com","peopleperhour.com","toptal.com","guru.com","contra.com","braintrust.com","usebraintrust.com","truelancer.com","freelancer.co.nz","freelancer.com.au","freelancer.in"],
  "🇪🇺 欧洲接单": ["fl.ru","codeur.com","useme.com","freelance.nl","free-work.com","freelancermap.de","twagofreelance.com","freelance.de","comet.co","worksome.com","beingguru.com","freelanceboard.it","freelancehunt.com"],
  "🇨🇳 中文接单": ["epwk.com","zbj.com","proginn.com","shixian.com","yunwork.com","yuanjisong.com","zb.oschina.net","tezign.com","680.com"],
  "🌏 亚太接单": ["coconala.com","crowdworks.jp","lancers.jp","sribu.com","fastwork.id","freelancing.my","workana.com","latinhire.com"],
  "💰 赏金悬赏": ["bugcrowd.com","hackerone.com","intigriti.com","huntr.co","huntr.com","algora.io","internetbugbounty.org","gitcoin.co","immunefi.com","openbugbounty.org","yeswehack.com"],
  "🤖 AI训练标注": ["mercor.com","alignerr.com","outlier.ai","dataannotation.tech","tasklet.ai","clickworker.com","microworkers.com","toloka.ai","appen.com","remotasks.com","scale.com"],
  "🧪 用户测试调研": ["usertesting.com","userinterviews.com","respondent.io","dscout.com","prolific.com"],
  "💼 项目制外包": ["giggrabbers.com","gigster.com","solidgigs.com","kolabtree.com","superside.com","crew.co","marketerhire.com","codeable.io","arc.dev","lemon.io","gun.io","upstack.com","jugglehire.com","commissioncrowd.com","catalant.com","devopsprojectshq.com","project-awesome.org","cryptotask.org"],
  "🏠 本地散活": ["taskrabbit.com"],
};

// 只保留实测活着的
const alive = new Map();
for (const o of [...a,...b]) {
  const st = String(o.status||"");
  if (st.includes("✅")) {
    const h = String(o.host).replace(/^www\./,"").toLowerCase();
    if (!alive.has(h)) alive.set(h, { host:h, name:o.name||h, status:st, proj:o.projHits||0, money:o.moneyHits||0 });
  }
}

// 按分类组装
const groups = [];
let total = 0;
for (const [cat, hosts] of Object.entries(GIG_HOSTS)) {
  const items = [];
  for (const h of hosts) {
    const k = h.replace(/^www\./,"").toLowerCase();
    const found = alive.get(k);
    if (found) items.push(found);
    else {
      // 实测未通过但平台真实（如 Upwork 403），仍标注
      const inExtra = [...a,...b].find(o=>String(o.host).toLowerCase().includes(k.split('.')[0]));
      if (inExtra) items.push({ host:k, name:inExtra.name||k, status:String(inExtra.status), proj:inExtra.projHits||0, money:inExtra.moneyHits||0 });
    }
  }
  if (items.length) { groups.push({ cat, items }); total += items.length; }
}

await fs.writeFile(S+"\\_GIG50_FINAL.json", JSON.stringify(groups,null,1), "utf8");
return { total, groups: groups.map(g=>g.cat+" : "+g.items.length) };
